module Main where

import Application.Script.Prelude
import Config
import IHP.AuthSupport.Authentication (hashPassword)
import qualified Application.Domain.Grade as GradeDomain
import qualified Data.Text as Text
import qualified Data.Text.IO as TextIO
import System.Environment (getEnv)
import System.Exit (die)
import qualified Text.Read as Read
import Control.Exception (SomeException)

ensure :: Bool -> IO ()
ensure condition = unless condition (error "Demonstração recusada: configuração, identidade ou manifesto divergente")

-- Stable academic keys only. UUIDs are generated by PostgreSQL on rowFirst creation.
offerings :: [(Text, Text, Text, Text, Text)]
offerings =
    [ ("DEMO-ALG", "Algoritmos", "DEMO-DOC-001", "Carlos Lima", "docente.algoritmos@example.test")
    , ("DEMO-BD", "Banco de Dados", "DEMO-DOC-002", "Mariana Rocha", "docente.bancodedados@example.test")
    , ("DEMO-ES", "Engenharia de Software", "DEMO-DOC-003", "Roberto Nunes", "docente.engenharia@example.test")
    , ("DEMO-REDES", "Redes de Computadores", "DEMO-DOC-004", "Fernanda Alves", "docente.redes@example.test")
    , ("DEMO-PF", "Programação Funcional", "DEMO-DOC-005", "Ricardo Souza", "docente.funcional@example.test")
    ]

main :: IO ()
main = seedMain `catch` (\(_ :: SomeException) -> die "Demonstração interrompida; consultas e credenciais omitidas.")

seedMain :: IO ()
seedMain = do
    mode <- getEnv "IHP_ENV"
    marker <- getEnv "SGA_DEMO_CONFIRM"
    ensure (mode == "Development" && marker == "development-demo")
    adminPassword <- secret "SGA_DEMO_ADMIN_PASSWORD"
    teacherPassword <- secret "SGA_DEMO_TEACHER_PASSWORD"
    studentPassword <- secret "SGA_DEMO_STUDENT_PASSWORD"
    students <- readCsv "docs/database/reorganizacao-demo-novos-estudantes.csv"
    enrollments <- readCsv "docs/database/reorganizacao-demo-50-matriculas.csv"
    assessments <- readCsv "docs/database/reorganizacao-demo-avaliacoes-planejadas.csv"
    validateManifests students enrollments assessments
    runScript config $ withoutQueryLogging do
        ensure isDevelopment
        -- This guard also applies when bypassing the Python wrapper.
        [(database, local)] <- unsafeSqlQuery "SELECT current_database()::text, inet_server_addr() IS NULL" () :: IO [(Text, Bool)]
        ensure (local && (database == "sga_demo" || "sga_demo_" `Text.isPrefixOf` database))
        withTransaction do
            unsafeSqlExecDiscardResult "SET LOCAL lock_timeout = '5s'" ()
            unsafeSqlExecDiscardResult "LOCK TABLE users,students,teachers,courses,subjects,teacher_subjects,enrollments,grades IN SHARE ROW EXCLUSIVE MODE" ()
            before <- snapshot
            _ <- adminAccount adminPassword
            course <- demoCourse
            forEach offerings \(code, title, registration, name, email) -> do
                subject <- demoSubject course code title
                teacher <- demoTeacher registration name email teacherPassword
                assignment <- query @TeacherSubject |> filterWhere (#teacherId, unpackId teacher.id) |> filterWhere (#subjectId, unpackId subject.id) |> fetchOneOrNothing
                when (isNothing assignment) do
                    _ <- newRecord @TeacherSubject |> set #teacherId (unpackId teacher.id) |> set #subjectId (unpackId subject.id) |> createRecord
                    pure ()
            forEach students \row -> case row of
                [registration, name, email, _, _, _] -> do
                    student <- demoStudent registration name email studentPassword
                    forEach (filter (\r -> rowFirst r == registration) enrollments) \entry -> case entry of
                        [_, code, teacherRegistration, _] -> do
                            subject <- query @Subject |> filterWhere (#code, code) |> fetchOne
                            teacher <- query @Teacher |> filterWhere (#registrationNumber, teacherRegistration) |> fetchOne
                            permission <- query @TeacherSubject |> filterWhere (#teacherId, unpackId teacher.id) |> filterWhere (#subjectId, unpackId subject.id) |> fetchOneOrNothing
                            ensure (isJust permission)
                            existing <- query @Enrollment |> filterWhere (#studentId, unpackId student.id) |> filterWhere (#subjectId, unpackId subject.id) |> fetchOneOrNothing
                            enrollment <- case existing of
                                Just record -> pure record
                                Nothing -> newRecord @Enrollment |> set #studentId (unpackId student.id) |> set #subjectId (unpackId subject.id) |> set #status Active |> createRecord
                            forEach (filter (\r -> rowFirst r == registration && r !! 1 == code && finalField r == "initial") assessments) \assessment -> case assessment of
                                [_, _, title, scoreText, weightText, _] -> do
                                    old <- query @Grade |> filterWhere (#enrollmentId, unpackId enrollment.id) |> filterWhere (#assessmentName, title) |> fetch
                                    ensure (length old <= 1)
                                    when (null old) do
                                        let score = number scoreText
                                        let weight = number weightText
                                        _ <- newRecord @Grade |> set #enrollmentId (unpackId enrollment.id) |> set #assessmentName title |> set #score (realToFrac score) |> set #weight (realToFrac weight) |> createRecord
                                        pure ()
                                _ -> ensure False
                        _ -> ensure False
                _ -> ensure False
            after <- snapshot
            -- Existing users, hashes, scores and all other records are immutable here.
            ensure (all (`elem` after) before)
        putStrLn ("Demonstração pronta: curso, cinco disciplinas/docentes, dez estudantes, 50 matrículas e 120 avaliações iniciais. Nenhuma senha existente foi alterada." :: Text)

secret :: String -> IO Text
secret name = do
    value <- cs <$> getEnv name
    ensure (Text.length value >= 12)
    pure value

rowFirst :: [Text] -> Text
rowFirst = fromMaybe (error "Linha vazia no manifesto") . head

finalField :: [Text] -> Text
finalField = fromMaybe (error "Linha vazia no manifesto") . last

number :: Text -> Double
number = fromMaybe (error "Número inválido no manifesto") . Read.readMaybe . Text.unpack

readCsv :: FilePath -> IO [[Text]]
readCsv path = map (Text.splitOn "," . Text.strip) . drop 1 . Text.lines <$> TextIO.readFile path

validateManifests :: [[Text]] -> [[Text]] -> [[Text]] -> IO ()
validateManifests students enrollments assessments = do
    let registrations = map (\i -> "DEMO-V2-" <> Text.justifyRight 3 '0' (show i)) ([1..10] :: [Int])
    let codes = map (\(code, _, _, _, _) -> code) offerings
    ensure (length students == 10 && all (\r -> length r == 6 && not (Text.null (r !! 1)) && "@" `Text.isInfixOf` (r !! 2) && r !! 3 == "RoleStudent") students)
    ensure (map rowFirst students == registrations && length (nub (map (!! 2) students)) == 10)
    ensure (length enrollments == 50 && all (\r -> length r == 4 && rowFirst r `elem` registrations && r !! 1 `elem` codes && finalField r == "active" && any (\(code, _, teacher, _, _) -> r !! 1 == code && r !! 2 == teacher) offerings) enrollments)
    ensure (length (nub (map (take 2) enrollments)) == 50)
    ensure (length assessments == 150 && all (\r -> length r == 6 && rowFirst r `elem` registrations && r !! 1 `elem` codes && r !! 2 `elem` ["DEMO V2 AV1", "DEMO V2 AV2", "DEMO V2 Trabalho"] && GradeDomain.notaValida (number (r !! 3)) && GradeDomain.pesoValido (number (r !! 4)) && finalField r == (if rowFirst r `elem` take 8 registrations then "initial" else "manual")) assessments)
    ensure (length (nub (map (take 3) assessments)) == 150)

newAccount :: (?modelContext :: ModelContext) => Text -> Text -> UserRole -> Text -> IO User
newAccount name email role password = do
    hash <- hashPassword password
    newRecord @User |> set #name name |> set #email email |> set #role_ role |> set #passwordHash hash |> createRecord

matchingAccount :: Text -> Text -> UserRole -> User -> Bool
matchingAccount name email role user = user.name == name && user.email == email && user.role_ == role

adminAccount :: (?modelContext :: ModelContext) => Text -> IO User
adminAccount password = do
    users <- query @User |> filterWhereCaseInsensitive (#email, "admin.demo@example.test") |> fetch
    case users of
        [] -> newAccount "Admin Demonstração" "admin.demo@example.test" Roleadmin password
        [user] -> ensure (matchingAccount "Admin Demonstração" "admin.demo@example.test" Roleadmin user) >> pure user
        _ -> error "Conta administrativa ambígua"

demoCourse :: (?modelContext :: ModelContext) => IO Course
demoCourse = do
    existing <- query @Course |> filterWhere (#code, "DEMO-CC") |> fetchOneOrNothing
    case existing of
        Nothing -> newRecord @Course |> set #name "Ciência da Computação" |> set #code "DEMO-CC" |> set #workload 300 |> createRecord
        Just course -> ensure (course.name == "Ciência da Computação" && course.workload == 300) >> pure course

demoSubject :: (?modelContext :: ModelContext) => Course -> Text -> Text -> IO Subject
demoSubject course code title = do
    existing <- query @Subject |> filterWhere (#code, code) |> fetchOneOrNothing
    case existing of
        Nothing -> newRecord @Subject |> set #name title |> set #code code |> set #courseId (unpackId course.id) |> set #workload 60 |> createRecord
        Just subject -> ensure (subject.name == title && subject.courseId == unpackId course.id && subject.workload == 60) >> pure subject

demoTeacher :: (?modelContext :: ModelContext) => Text -> Text -> Text -> Text -> IO Teacher
demoTeacher registration name email password = do
    existing <- query @Teacher |> filterWhere (#registrationNumber, registration) |> fetchOneOrNothing
    users <- query @User |> filterWhereCaseInsensitive (#email, email) |> fetch
    case (existing, users) of
        (Nothing, []) -> do
            user <- newAccount name email Roleteacher password
            newRecord @Teacher |> set #name name |> set #email email |> set #registrationNumber registration |> set #userId (Just (unpackId user.id)) |> createRecord
        (Just teacher, [user]) -> ensure (teacher.name == name && teacher.email == email && teacher.userId == Just (unpackId user.id) && matchingAccount name email Roleteacher user) >> pure teacher
        _ -> error "Identidade docente divergente"

demoStudent :: (?modelContext :: ModelContext) => Text -> Text -> Text -> Text -> IO Student
demoStudent registration name email password = do
    existing <- query @Student |> filterWhere (#enrollmentNumber, registration) |> fetchOneOrNothing
    users <- query @User |> filterWhereCaseInsensitive (#email, email) |> fetch
    case (existing, users) of
        (Nothing, []) -> do
            user <- newAccount name email Rolestudent password
            newRecord @Student |> set #name name |> set #email email |> set #enrollmentNumber registration |> set #userId (Just (unpackId user.id)) |> createRecord
        (Just student, [user]) -> ensure (student.name == name && student.email == email && student.userId == Just (unpackId user.id) && matchingAccount name email Rolestudent user) >> pure student
        _ -> error "Identidade estudantil divergente"

snapshot :: (?modelContext :: ModelContext) => IO [(Text, Text, Text)]
snapshot = unsafeSqlQuery "SELECT 'users',id::text,md5(to_jsonb(t)::text) FROM users t UNION ALL SELECT 'students',id::text,md5(to_jsonb(t)::text) FROM students t UNION ALL SELECT 'teachers',id::text,md5(to_jsonb(t)::text) FROM teachers t UNION ALL SELECT 'courses',id::text,md5(to_jsonb(t)::text) FROM courses t UNION ALL SELECT 'subjects',id::text,md5(to_jsonb(t)::text) FROM subjects t UNION ALL SELECT 'teacher_subjects',id::text,md5(to_jsonb(t)::text) FROM teacher_subjects t UNION ALL SELECT 'enrollments',id::text,md5(to_jsonb(t)::text) FROM enrollments t UNION ALL SELECT 'grades',id::text,md5(to_jsonb(t)::text) FROM grades t" ()
